INSERT INTO `hotels` VALUES
(1,'limak-cyprus-deluxe-hotel-single','Limak Cyprus Deluxe Hotel',5,'Bafra, İskele / Northern Cyprus','Ultra All Inclusive (UAI)',5,'Location and Transportation: Located right on the beachfront in the Bafra region, the property is 40 km away from Famagusta.\nConcept: Ultra All Inclusive (UAI)- 5 stars\nBeach and Pools: In addition to its own 200-meter-long private sandy beach, the facility features indoor and outdoor swimming pools as well as an aquapark with 7 slides.','<p>Limak Cyprus Deluxe Hotel, Vokolidha\'da restoran, fitness merkezi, bar ve bahçe sunmaktadır. Bu 5 yıldızlı otel, 24 saat açık resepsiyon, oda servisi ve ücretsiz Wi-Fi sunmaktadır.</p>\n<p>Otelin tüm odaları elektrikli su ısıtıcısı ile donatılmıştır. Odalar klima ve düz ekran TV ile donatılmıştır ve Limak Cyprus Deluxe Hotel\'in bazı odalarında balkon vardır.</p>\n<p>Tesis, sauna ve teras içeren 5 yıldızlı konaklama birimleri sunmaktadır.</p>\n<p>En yakın havaalanı olan Ercan Uluslararası Havaalanı, Limak Cyprus Deluxe Hotel\'e 42 km uzaklıktadır.</p>',NULL,'uploads/2025/05/10-limak-deluxe-general-view-night-bafra.jpg','','',1,'','',3,1),
(2,'salamis-hotel','Salamis Hotel',3,'Salamis, Famagusta / Northern Cyprus','Ultra All Inclusive (UAI)',5,'Location and Transportation: Situated right on the beachfront, just moments away from the historic Ancient City of Salamis.\nConcept: Ultra All Inclusive (UAI) – 5 stars\nBeach and Pools: Features a private fine-sand beach and a pier. The property includes indoor and outdoor swimming pools, children\'s pools, and an aquapark operating during the summer season.\nFood and Beverage: Operating under the Ultra All Inclusive concept, the hotel offers a total of 12 restaurants and bars. Alongside the main buffet restaurant, a\'la carte restaurants specializing in Chinese, Italian, and Turkish cuisines are available.\nSPA, Casino, and Event Spaces: Houses the Lemon Spa & Wellness center (featuring a Turkish bath, sauna, massage services, and a fitness center), a casino open to guests aged 25 and over, and 9 meeting/event halls.','<p>Salamis Hotel, Kuzey Kıbrıs’ın Gazimağusa bölgesinde denize sıfır konumuyla konforlu bir tatil deneyimi sunan lüks bir tesistir. Modern odaları, geniş plajı, açık ve kapalı yüzme havuzları, spa merkezi ve casino hizmetiyle hem dinlenmek hem de eğlenmek isteyen misafirler için idealdir. Salamis Bay bölgesinin doğal güzellikleriyle çevrili otel, misafirlerine kaliteli hizmet ve huzurlu bir atmosfer vaat eder.</p>',NULL,'uploads/2025/10/362657917.jpg','','',1,'','',4,1),
(3,'elexus-hotel','Elexus Hotel',2,'Çatalköy, Kyrenia / Northern Cyprus','Ultra All Inclusive (UAI)',5,'Location: Çatalköy, Kyrenia / Northern Cyprus\nConcept: Ultra All Inclusive (UAI)- 5 stars\nFeatured Amenities: It features a private sandy beach, an adults-only Miami-style beach club, 4 outdoor swimming pools, 2 heated indoor pools, an infinity pool, a massive 6,000 m² aqua park, and a 600-meter electric go-kart track.','',NULL,'uploads/2025/10/elexus-hotel-resort-casino-301915-e1641631786666.jpg','','',1,'','',2,1),
(4,'concorde-aria-hotel-casino','Concorde Aria Hotel & Casino',2,'Çatalköy, Kyrenia / Northern Cyprus','Ultra All Inclusive (UAI)',5,'Location: Çatalköy, Kyrenia / Northern Cyprus\nConcept: Ultra All Inclusive (UAI)- 5 stars\nFeatured Amenities: Casino, SPA & wellness center, indoor swimming pool, à la carte restaurants, and a kids\' club','','','uploads/2026/11/resim1-720x475.jpg','','',1,'','',1,1),
(5,'lords-palace-lagoon-hotel','Lords Palace Lagoon Hotel',2,'Ozanköy, Kyrenia / Northern Cyprus','FB+',5,'Location and Transportation: Situated right on the beachfront in the Ozanköy area of Kyrenia.\nConcept: FB+ ( 5 stars)\nBeach and Pools: Featuring its own private sandy beach and a pier, the hotel offers expansive outdoor lagoon pools, a heated indoor pool, and children\'s pools.\nFood, Beverage, and Entertainment: Alongside the main buffet restaurant, 2 a\'la carte restaurants and various bars are available. The property also houses a casino, a spacious SPA & wellness center, a fitness center, and a kids\' club.','',NULL,'uploads/2026/11/resim2-720x475.jpg','','',1,'','',5,1),
(6,'cratos-hotel','Cratos Hotel',2,'Kyrenia – Çatalköy','FB+',5,'Location and Transportation: Kyrenia – Çatalköy\nConcept: FB+  (5 stars)\nBeach and Pools: Features a private sandy beach (La Plage) and a pier. The property includes a 1,350 m² main outdoor swimming pool, a heated indoor pool, and a children\'s pool.\nFood, Beverage, and Port Cratos: Alongside the main buffet restaurant, the Port Cratos beachfront complex offers a\'la carte restaurants such as Mey Blue (seafood), Ocakbaşı, and Golden Cage, as well as the Coco Bongo and Cage Club nightclubs.\nSPA, Casino, and Event Spaces: Houses a 3,000 m² SPA center (featuring a Turkish bath, sauna, steam room, VIP treatment rooms, and a fitness center), a 4,000 m² casino, the Cratoys Mini Club for ages 0–12, the Huckleberry arcade, and 9 meeting rooms including the Nobel Ballroom.','',NULL,'uploads/2026/11/images.jpg','','',1,'','',17,1),
(7,'vuni-palace-hotel','Vuni Palace Hotel',2,'Kyrenia – Karakum','HB-AI',5,'Location and Transportation: Kyrenia – Karakum\nConcept: HB-AI 5 stars\nBeach and Pools: Features a 100-meter-long private sand-and-pebble beach and a pier. The property includes a total of 3 pools: a spacious \"Z\"-shaped outdoor swimming pool, an indoor swimming pool, and a children\'s pool.\nFood and Beverage: Alongside the main buffet restaurant (Terrace Restaurant), Mirror A\'la Carte Restaurant, a lobby bar, a terrace bar, a vitamin bar, and beach/pool bars are available.\nSPA, Casino, and Event Spaces: Houses the Velora Spa center (featuring a Turkish bath, sauna, steam room, snow bath, massage services, and a fitness center), a casino, an amphitheater, a mini club for ages 4–12, and conference/meeting halls.','',NULL,'uploads/2026/11/538734831.jpg','','',1,'','',16,1),
(8,'merit-royal-diamond-hotel','Merit Royal Diamond Hotel',2,'Kyrenia – Alsancak','Ultra All Inclusive (UAI)',5,'Location and Transportation: Kyrenia – Alsancak\nConcept: Ultra All Inclusive (UAI) – 5 stars\nBeach and Pools: Offers access to the private sandy beach and pier in Zephyros Bay, shared with its sister properties (Merit Royal and Merit Royal Premium), with 24/7 shuttle service operating between the properties. The hotel features spacious outdoor swimming pools and an indoor pool.\nFood and Beverage: Alongside the Imperial / Crystal Imperial main buffet restaurant, The Steakhouse a\'la carte restaurant, Whiskey Lounge, Tea Lounge, Merit Shisha, Pool Bar, and a 24-hour lobby bar are available.\nSPA, Casino, and Congress Center: The 3,600 m² indoor SPA center features one of the largest indoor pools on the island, 7 VIP massage rooms equipped with private Turkish baths, saunas, and jacuzzis, as well as a salt room, a snow fountain, and a squash court. Direct access to the Merit Royal Casino is provided from the lower floor of the complex, while the Diamond Congress Center offers a 2,400–2,500 m² column-free ballroom/concert hall, 12 meeting rooms, and a 250-seat amphitheater.','',NULL,'uploads/2026/11/381860076.jpg','','',1,'','',15,1),
(9,'merit-royal-premium-hotel','Merit Royal Premium Hotel',2,'Kyrenia – Alsancak','Ultra All Inclusive (UAI)',5,'Location and Transportation: Kyrenia – Alsancak\nConcept: Ultra All Inclusive (UAI) – 5 stars\nBeach and Pools: Features its own private sandy beach and a wooden pier in Zephyros Bay. The property includes an infinity pool, outdoor swimming pools, a heated indoor pool, and a children\'s pool.\nFood and Beverage: Alongside the Premium Main Restaurant and a 24-hour lobby bar, the complex offers a\'la carte restaurants serving world cuisines (Dragon, Blue Sea, A La Turca, Bella Merit), Cafe Verde, Merit Shisha, and Maxim Royal, which hosts stage shows on Saturday evenings.\nSPA, Casino, and Kids\'/Event Spaces: Houses the 3,500 m² two-story Royal Spa & Wellness center (featuring 4 Turkish baths, 4 saunas, salt and steam rooms, massage therapies, and a fitness center), the 5,500 m² Merit Royal Casino, the Meritta Kids Club for ages 0–12, Funzone, Art House, and 4 meeting/congress halls.','',NULL,'uploads/2026/11/405935039.jpg','','',1,'','',14,1),
(10,'merit-park-hotel','Merit Park Hotel',2,'Karaoğlanoğlu, Kyrenia','Ultra All Inclusive (UAI)',5,'Location and Transportation: Karaoğlanoğlu, Kyrenia\nConcept: Ultra All Inclusive (UAI) – 5 stars\nBeach and Pools: Features a platform beach (Giamare Beach), a pier, and private cabanas. The property includes 2 outdoor swimming pools, a heated indoor pool, and children\'s pools.\nSPA, Casino, and Event Spaces: Houses a 3,400 m² casino, the Merit Park Spa & Wellness center (featuring a Turkish bath, sauna, Far Eastern/Ayurvedic massages, and a fitness center), the Meritta kids\' club, a Pony Club, a tennis court.','',NULL,'uploads/2026/11/bina-kumbar.jpg','','',1,'','',13,1),
(11,'kaya-palazzo-hotel-kyrenia','Kaya Palazzo Hotel Kyrenia',2,'Kyrenia – Karaoğlanoğlu','FB+ and BB',5,'Location and Transportation: Kyrenia – Karaoğlanoğlu\nConcept: FB+ and BB (5 stars)\nBeach and Pools: Features its own private sandy beach, private pavilions, and a 2,000 m² platform pier. The property includes a main outdoor swimming pool, a quiet adult-only pool for guests aged 16 and over (+16), a children\'s pool, and an indoor pool.\nFood and Beverage: Operating on Full Board Plus and Bed & Breakfast concepts, the hotel offers the Palazzo Buffet main restaurant alongside a\'la carte restaurants including Develi (kebab/meat), Dostlar Eskiyer (seafood), and the seasonal Palazzo Beach restaurant, as well as a patisserie and various bars.\nSPA, Casino, and Event Spaces: Houses the 2,000 m² Palazzo Spa & Fitness center (featuring a Turkish bath, sauna, steam and snow rooms, massage services, and a gym), the 5,000 m² Palazzo Casino, the Pozzo Mini Club kids\' club, and 1,300 m² of congress/meeting halls.','',NULL,'uploads/2026/11/kaya-palazzo-resort-casino.jpg','','',1,'','',12,1),
(12,'acapulco-hotel','Acapulco Hotel',2,'Çatalköy, Kyrenia / Northern Cyprus','FB+',5,'Location and Transportation: Çatalköy, Kyrenia / Northern Cyprus- It is 8 km away from Kyrenia city center\nConcept: FB+ ( 5 stars)\nBeach and Pools: Features a 1-km-long uninterrupted private sandy beach. The property includes outdoor swimming pools, a heated indoor pool, children\'s pools, and a large aquapark with 24 slides operating during the summer season.\nSPA, Casino, Congress, and Sports: Houses the Ocean Spa & Wellness center (featuring a Turkish bath, sauna, saltwater pool, and massage therapies), a 24-hour casino, 14 different meeting/congress halls with capacities ranging from 100 to 2,000 guests, an evening funfair, a mini club, and 2 FIFA-standard football pitches.',NULL,NULL,'uploads/oteller/acapulco-resort-convention.jpg','','',1,'','',7,1),
(13,'arkin-iskele-hotel','Arkin Iskele Hotel',5,'Iskele coast','Ultra All Inclusive (UAI)',5,'Location and Transportation: Iskele coast\nConcept: Ultra All Inclusive (UAI) – 5 stars\nBeach and Pools: Features a 1-km-long private sandy beach and 1 pier. The property includes outdoor swimming pools, a 220 m² indoor swimming pool, a children\'s pool, and water slides (aquapark) for both adults and children.\nFood and Beverage: Alongside the main buffet restaurant, 4 different a\'la carte restaurants (Seafood, Grill/Ocakbaşı, Italian, and Beach Snack), 2 cafes, and 4 bars are available.',NULL,NULL,'uploads/oteller/arkin-iskele.jpg','','',1,'','',9,1),
(14,'concorde-luxury-hotel','Concorde Luxury Hotel',5,'Bafra','Ultra All Inclusive (UAI)',5,'Location and Transportation: Bafra\nConcept: Ultra All Inclusive (UAI) – 5 stars\nBeach and Pools: Features its own 300-meter-long private sandy beach. The property includes a total of 10 indoor and outdoor swimming pools, along with an aquapark featuring slides for both adults and children.\nFood and Beverage: Alongside the main buffet restaurant, 6 different a\'la carte restaurants offering flavors from world cuisines, a brasserie, snack areas, and numerous bars are available.\nSPA, Casino, and Kids\' Areas: Houses the Sentire SPA Center (featuring a Turkish bath, sauna, steam room, and massage therapies), the 1,500 m² Moppet Kids Club, a fully equipped casino, and spacious congress/meeting halls.',NULL,NULL,'uploads/oteller/concorde-luxury-resort-995344-1.webp','','',1,'','',6,1),
(15,'grand-sapphire-hotel','Grand Sapphire Hotel',5,'Iskele Long Beach / Northern Cyprus','Ultra All Inclusive (UAI)',5,'Location and Transportation: Located in the Iskele Long Beach area, the property is approximately 200–300 meters from the sea, offering continuous shuttle service to its private sandy beach (Pera Mackenzie).\nConcept: Ultra All Inclusive (UAI) – 5 stars (7-Star Living Experience)\nFood and Beverage: Alongside the main buffet restaurant, the hotel features a\'la carte restaurants, Fogo Brasserie & Bar, Skyline Lounge & Bar, Crow\'s Irish Pub, Mia Terrace Bar, and the beachfront Pera Mackenzie Restaurant.\nSPA, Casino, and Event Spaces: Houses the Teratai Spa & Wellness center located on the 3rd and 26th floors (featuring VIP Turkish baths, a sauna, anti-aging treatments, and massage therapies), the 2,700 m² Grand Sapphire Casino, the 1,660 m² Boulevard Ballroom with a capacity of 1,520 guests, a Game Zone arcade, a cinema, a funfair, and a mini club.',NULL,NULL,'uploads/oteller/grand-sapphire.jpg','','',1,'','',10,1),
(16,'kaya-artemis-hotel','Kaya Artemis Hotel',5,'Bafra','Ultra All Inclusive (UAI)',5,'Location and Transportation: Bafra\nConcept: Ultra All Inclusive (UAI) – 5 stars\nBeach and Pools: Features a 250-meter-long private fine-sand beach and a pier. The property includes indoor and outdoor swimming pools, VIP pool options, and an aquapark with 7 slides.\nFood and Beverage: Alongside the main buffet restaurant, 3 different a\'la carte restaurants (Sirius, etc.) and 8 bars are available.\nSPA, Casino, and Event Spaces: Houses a Turkish bath, sauna, steam room, massage services, and a fitness center, along with the 3,600 m² Artemis Casino, a Kids Club for ages 4–12, tennis courts, football pitches, and a spacious congress center.',NULL,NULL,'uploads/oteller/kaya-artemis.jpg','','',1,'','',8,1),
(17,'lords-palace-hotel-kyrenia','Lords Palace Hotel Kyrenia',2,'Kyrenia city center','SAI- HB',5,'Location and Transportation: Kyrenia city center\nConcept: SAI- HB – 5 stars\nBeach and Pools: Features its own private sandy beach and the Bella Marin pier/beach complex. The property includes a semi-Olympic outdoor swimming pool, a heated indoor pool, a children\'s pool, and a rooftop (Sky Lounge) infinity pool overlooking Kyrenia.\nFood and Beverage: Alongside the main buffet restaurant, the on-site Bella Marin lifestyle area offers a\'la carte restaurants such as Khephal (seafood) and Kömür Steak & Ocakbaşı, as well as the Sky Lounge terrace bar and a nightclub (Odyssey).\nSPA, Casino, and Event Spaces: Houses a 1,000 m² Japanese-concept SPA & Wellness center (featuring a Turkish bath, sauna, jacuzzi, massage services, and a fitness center), a 2,500 m² casino, the Kids Planet kids\' club, and 3 meeting/ballroom halls.',NULL,NULL,'uploads/oteller/lords-palace-girne.jpg','','',1,'','',11,1);
