CREATE TABLE `sections` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `skey` varchar(40) NOT NULL,
  `name` varchar(120) NOT NULL DEFAULT '',
  `kicker` varchar(190) NOT NULL DEFAULT '',
  `title` varchar(255) NOT NULL DEFAULT '',
  `body` text DEFAULT NULL,
  `image` varchar(255) NOT NULL DEFAULT '',
  `btn_text` varchar(120) NOT NULL DEFAULT '',
  `btn_url` varchar(255) NOT NULL DEFAULT '',
  `style` varchar(20) NOT NULL DEFAULT 'light',
  `layout` varchar(20) NOT NULL DEFAULT '',
  `lim` int(11) NOT NULL DEFAULT 0,
  `sort` int(11) NOT NULL DEFAULT 0,
  `active` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `skey` (`skey`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
