INSERT INTO `sections` VALUES
(1,'hero','Slider / Video','','','','','','','dark','',0,1,1),
(2,'intro','Tanıtım (Hakkımızda özeti)','Hakkımızda','Cyprus Touristic','<p>CYPRUS TOURISTIC, dünya arenasında Kuzey Kıbrıs’ı ve Türkiye’yi tanıtmak için faaliyet göstermektedir. Kuzey Kıbrıs ve Türkiye’deki ihtiyaçlara heyecan verici ve uygun maliyetli çözümler sunan MICE , düğün ve tatil turizmini yönetmekte ve organize etmektedir. Hedefimiz, tüm piyasaları Türk ve Kuzey Kıbrıs misafirperverliğinin samimiyeti ve sıcaklığıyla profesyonel ve uzman bir şekilde zamanında yanıt vererek tanıştırmaktır. Cyprus Touristic, dünyanın dört bir yanından toplantı, teşvik, seminer katılımcılarının yanı sıra düğün ve ve özel etkinlik gruplarına yıl boyunca titizlikle hizmet vermektedir. Ayrıca Cyprus Touristic düzenli ve charter uçuşların biletlenmesi, otel rezervasyonu ve tüm lojistik konularında üst düzey bir hizmet sağlayıcıya sahiptir.</p>\n<p>Cyprus Touristic, dünyanın her yerinden turizm profesyonelleri ile çalışan 50’den fazla uzmandan oluşan dinamik bir ekibe sahiptir. Tekliflerimizi ve programlarımızı sadece size özel olarak tasarlıyoruz.</p>','uploads/2021/10/kipr-more-iakhty.jpg','Hakkımızda','hakkimizda','light','',0,2,1),
(3,'marquee','Kayan otel adları şeridi','','','','','','','brand','',0,3,1),
(4,'hotels','Oteller','Kuzey Kıbrıs','Rezervasyon Yap','','','Tüm Oteller','oteller','soft','grid',16,4,1),
(5,'services','Hizmetler','Cyprus Touristic','Hizmetlerimiz','Hayalinizdeki seyehat planını Cyprus Touristic ile planlayın, rüyalarınızı yaşayın.','','','','light','',0,5,1),
(6,'counters','Sayaçlar','','','','uploads/2024/11/karpaz4.jpg','','','brand','',0,6,1),
(7,'regions','Bölgeler (Kuzey Kıbrıs)','Cyprus Touristic','Kuzey Kıbrıs','Kıbrıs rüyanızı gerçekleştirebileceğiniz bölgeler…','','','','light','',0,7,1),
(8,'why','Garanti ediyoruz / Öz değerler','Cyprus Touristic','Garanti ediyoruz','','','Hakkımızda','hakkimizda','soft','',0,8,1),
(9,'factsheets','Hotel Factsheets','PDF','Hotel Factsheets','','','','','light','',0,9,1),
(10,'cta','Çağrı bandı (Talep Formu)','Talep Formu','Hayalinizdeki Kıbrıs tatilini \"Cyprus Touristic\" ile keşfedin...','Kuzey Kıbrıs tatilinizi planlarken hayallerinize ortak olup bütçenize en uygun tatili birlikte organize edelim.','uploads/2021/10/karpaz-altinkum-sahili.jpg','Talep Formu','talep-formu','brand','',0,10,1),
(11,'contact','İletişim kartları','İletişim','Bizimle İletişime Geçin','Aşağıdaki iletişim kanallarından bize ulaşabilirsiniz.','','İletişim','iletisim','soft','',0,11,1);
