INSERT INTO `services` VALUES
(1,'mice','M.I.C.E','M.I.C.E','20 yıldan fazla işletme deneyimine dayanan, MICE reklam grubu seyahat ihtiyaçlarınızı karşılayacak bilgi birikimine sahibiz. Cyprus Touristic olarak, Kıbrıs kültürümüzü ve uluslararası iş zekamızı, mümkün olan en uygun fiyat ile, en yüksek seviyede hizmet sunmak için birleştiriyoruz. Toplantılar, konferanslar ve etkinlikler için kapsamlı ve uygun maliyetli çözümler sunan MICE ve grup seyahat programlarınızın planlanması ve uygulaması süresince destek oluyoruz.','<p>20 yıldan fazla işletme deneyimine dayanan, MICE reklam grubu seyahat ihtiyaçlarınızı karşılayacak bilgi birikimine sahibiz. Cyprus Touristic olarak, Kıbrıs kültürümüzü ve uluslararası iş zekamızı, mümkün olan en uygun fiyat ile, en yüksek seviyede hizmet sunmak için birleştiriyoruz. Toplantılar, konferanslar ve etkinlikler için kapsamlı ve uygun maliyetli çözümler sunan MICE ve grup seyahat programlarınızın planlanması ve uygulaması süresince destek oluyoruz.</p>\n<p><strong>Toplantı – Kurumsal – Kongre – Etkinlik</strong></p>','uploads/2024/11/meetings-rooms-new-4.png','users','','',1,1),
(2,'kurumsal','Kurumsal','SEYAHAT','İhtiyaçlarınıza çözüm sunmak için öncülük ediyoruz. Kurumsal seyahatinizi yönetiyoruz. Büyük ve küçük işletmeler için seyahat masraflarınızı kontrol altına alıyoruz. Yerel Pazar bilgimiz ile ileri teknolojileri kullanıyor, lider havayolu şirketleri ve oteller ile inanılmaz fırsatlar sunuyoruz.','<p>İhtiyaçlarınıza çözüm sunmak için öncülük ediyoruz. Kurumsal seyahatinizi yönetiyoruz. Büyük ve küçük işletmeler için seyahat masraflarınızı kontrol altına alıyoruz. Yerel Pazar bilgimiz ile ileri teknolojileri kullanıyor, lider havayolu şirketleri ve oteller ile inanılmaz fırsatlar sunuyoruz.</p>\n<h3>SUNDUKLARIMIZ</h3>\n<ul><li>İş seyahat masraflarınızı en aza indiriyoruz</li><li>En iyi çözümleri sunuyoruz</li><li>Kişi ve kuruma özel raporlamalar hazırlıyoruz</li><li>Profesyonel danışmanlık</li><li>Destek hizmetleri</li></ul>\n<h3>GÜÇLÜ YÖNLERİMİZ</h3>\n<ul><li>Konumuzda uzmanız</li><li>En iyi havayolları ile en özel teklifler</li><li>Dünya çapında otel ve araç kiralama ortaklıkları</li><li>Küresel ağımızda yüksek pazarlık gücü</li></ul>','uploads/2024/11/kurumsal-yonetimde-paydaslarin-rolu-ve-sorumluluklari.webp','briefcase','','',2,1),
(3,'tatil','Tatil','TATİL SEYAHATİ','Kuzey Kıbrıs tatilinizi planlarken hayallerinize ortak olup bütçenize en uygun tatili birlikte organize edelim.','<p>Kuzey Kıbrıs tatilinizi planlarken hayallerinize ortak olup bütçenize en uygun tatili birlikte organize edelim.</p>\n<h3>Hizmetlerimiz ;</h3>\n<ul><li>Otel rezervasyon hizmeti</li><li>Uygun fiyatlı uçak bileti</li><li>Havalimanı – otel – havalimanı transferleri</li><li>Otel rehberlik hizmeti</li><li>Günlük tur organizasyonları</li></ul>','uploads/2024/11/1683639135.webp','palm','','',3,1);
/*!40000 ALTER TABLE `services` ENABLE KEYS */;
